changeSet.sql:
CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.noeud_chemin() RETURNS trigger LANGUAGE plpgsql AS $corps$
DECLARE
    parent RECORD;
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.chemin := '/' || NEW.id::text || '/';
        NEW.nature := 'ESPACE';
    ELSE
        SELECT n.chemin, n.usage_espace INTO parent FROM ${database.defaultSchemaName}.noeud n WHERE n.id = NEW.parent_id;
        IF parent.chemin IS NULL THEN
            RAISE EXCEPTION 'Noeud parent introuvable : %', NEW.parent_id USING ERRCODE = 'foreign_key_violation';
        END IF;
        IF position('/' || NEW.id::text || '/' IN parent.chemin) > 0 THEN
            RAISE EXCEPTION 'Un noeud ne peut pas etre deplace dans sa propre descendance' USING ERRCODE = 'check_violation';
        END IF;
        NEW.chemin := parent.chemin || NEW.id::text || '/';
        NEW.nature := 'DOSSIER';
        -- Un dossier a l'usage de son espace (métier ou échange).
        NEW.usage_espace := parent.usage_espace;
    END IF;
    RETURN NEW;
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.noeud_chemin_enfants() RETURNS trigger LANGUAGE plpgsql AS $corps$
BEGIN
    IF NEW.chemin IS DISTINCT FROM OLD.chemin OR NEW.usage_espace IS DISTINCT FROM OLD.usage_espace THEN
        UPDATE ${database.defaultSchemaName}.noeud SET chemin = NEW.chemin || id::text || '/', usage_espace = NEW.usage_espace
         WHERE parent_id = NEW.id;
    END IF;
    RETURN NULL;
END
$corps$

