CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.noeud_chemin() RETURNS trigger LANGUAGE plpgsql AS $corps$
DECLARE
    chemin_parent VARCHAR(4000);
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.chemin := '/' || NEW.id::text || '/';
        NEW.nature := 'ESPACE';
    ELSE
        SELECT n.chemin INTO chemin_parent FROM ${database.defaultSchemaName}.noeud n WHERE n.id = NEW.parent_id;
        IF chemin_parent IS NULL THEN
            RAISE EXCEPTION 'Noeud parent introuvable : %', NEW.parent_id USING ERRCODE = 'foreign_key_violation';
        END IF;
        IF position('/' || NEW.id::text || '/' IN chemin_parent) > 0 THEN
            RAISE EXCEPTION 'Un noeud ne peut pas etre deplace dans sa propre descendance' USING ERRCODE = 'check_violation';
        END IF;
        NEW.chemin := chemin_parent || NEW.id::text || '/';
        NEW.nature := 'DOSSIER';
    END IF;
    RETURN NEW;
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.noeud_chemin_enfants() RETURNS trigger LANGUAGE plpgsql AS $corps$
BEGIN
    IF NEW.chemin IS DISTINCT FROM OLD.chemin THEN
        UPDATE ${database.defaultSchemaName}.noeud SET chemin = NEW.chemin || id::text || '/' WHERE parent_id = NEW.id;
    END IF;
    RETURN NULL;
END
$corps$
